redirects = {f"/lp/campaign-{i:03d}": f"/lp/c/{i:03d}" for i in range(1, 301)}
redirects["/lp/c/007"] = "/lp/c/107"        # 사슬
redirects["/lp/c/150"] = "/lp/campaign-150"  # 고리

def resolve(path, limit=5):
    seen = [path]
    while path in redirects and len(seen) <= limit:
        path = redirects[path]
        if path in seen:
            return seen + [path], "loop"
        seen.append(path)
    return seen, "ok" if len(seen) <= 2 else "chain"

bad = {}
for src in redirects:
    hops, st = resolve(src)
    if st != "ok":
        bad.setdefault(st, []).append(" -> ".join(hops))
print("rules:", len(redirects))
for k, v in bad.items():
    print(k, len(v), v[0])

# rules: 302
# chain 1 /lp/campaign-007 -> /lp/c/007 -> /lp/c/107
# loop 2 /lp/campaign-150 -> /lp/c/150 -> /lp/campaign-150

def lum(hexc):
    r, g, b = (int(hexc[i:i + 2], 16) / 255 for i in (1, 3, 5))
    f = lambda c: c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4
    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b)

def ratio(a, b):
    la, lb = sorted([lum(a), lum(b)], reverse=True)
    return (la + 0.05) / (lb + 0.05)

for fg, bg in [("#999999", "#FFFFFF"), ("#767676", "#FFFFFF"), ("#FFFFFF", "#E60012")]:
    r = ratio(fg, bg)
    print(fg, "on", bg, f"{r:.2f}:1", "pass" if r >= 4.5 else "fail")

# #999999 on #FFFFFF 2.85:1 fail
# #767676 on #FFFFFF 4.54:1 pass
# #FFFFFF on #E60012 4.80:1 pass
